mapper.select:
SELECT group_no,COUNT(*) AS total,SUM((done_mask & 1)!=0) AS en_to_zh,
    SUM((done_mask & 2)!=0) AS zh_to_en,SUM((done_mask & 4)!=0) AS audio_to_both
FROM sr_english_vocabulary_plan_item WHERE account_id=#{accountId} AND group_no > #{after}
GROUP BY group_no ORDER BY group_no LIMIT #{limit}

SELECT pi.word_id,pi.sort_no,pi.group_no,pi.done_mask,pi.word_json,(w.id IS NULL) AS unavailable
FROM sr_english_vocabulary_plan_item pi LEFT JOIN sr_english_vocabulary_word w ON w.id=pi.word_id
WHERE pi.account_id=#{accountId} AND pi.sort_no > #{after}
AND pi.group_no=#{groupNo}
ORDER BY pi.sort_no LIMIT #{limit}

mapper.update:
UPDATE sr_english_vocabulary_plan SET status=CASE WHEN EXISTS
    (SELECT 1 FROM sr_english_vocabulary_plan_item WHERE account_id=#{accountId} AND done_mask!=7) THEN 'ACTIVE' ELSE 'COMPLETED' END,
    updated_at=#{now} WHERE account_id=#{accountId}

mapper.select:
SELECT  FROM sr_english_vocabulary_mode_memory mm
WHERE account_id=#{accountId} AND next_review_at <= #{cursor.asOf}
    AND EXISTS(SELECT 1 FROM sr_english_vocabulary_word w WHERE w.id=mm.word_id)

    AND (next_review_at > #{cursor.dueAt} OR (next_review_at=#{cursor.dueAt} AND word_id > #{cursor.wordId})
    OR (next_review_at=#{cursor.dueAt} AND word_id=#{cursor.wordId} AND direction > #{cursor.direction}))

ORDER BY next_review_at,word_id,direction LIMIT #{limit}
